      <h1 id="page-title">Contact our support team</h1>
      <p class="intro">Send us your details and we&apos;ll get back to you as soon as possible.</p>

      <form id="support-form" novalidate>
        <div class="fields">
          <div class="form-field">
            <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
            <input id="full-name" name="fullName" type="text" autocomplete="name" required>
            <p id="full-name-error" class="error" hidden></p>
          </div>

          <div class="fields two-column">
            <div class="form-field">
              <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
              <input id="email-address" name="emailAddress" type="email" autocomplete="email" required>
              <p id="email-address-error" class="error" hidden></p>
            </div>

            <div class="form-field">
              <label for="phone-number">Phone number</label>
              <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" aria-describedby="phone-number-help">
              <p id="phone-number-help" class="help">Enter a number in international format if possible, such as +1 555 123 4567.</p>
            </div>
          </div>
        </div>

        <div class="actions">
          <button type="submit">Send message</button>
          <p id="form-status" class="status" role="status" aria-live="polite" hidden></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const status = document.getElementById('form-status');
    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        message: 'Error: Enter your full name.'
      },
      emailAddress: {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        message: 'Error: Enter a valid email address.'
      }
    };

    function setFieldError(key, message) {
      const { input, error } = fields[key];
      input.setAttribute('aria-invalid', 'true');
      error.textContent = message;
      error.hidden = false;
      input.setAttribute('aria-describedby', error.id);
    }

    function clearFieldError(key) {
      const { input, error } = fields[key];
      input.removeAttribute('aria-invalid');
      error.hidden = true;
      error.textContent = '';
      input.removeAttribute('aria-describedby');
    }

    function validateField(key) {
      const { input } = fields[key];
      const value = input.value.trim();

      if (key === 'fullName') {
        if (!value) {
          setFieldError(key, fields[key].message);
          return false;
        }
      }

      if (key === 'emailAddress') {
        if (!value || !input.checkValidity()) {
          setFieldError(key, fields[key].message);
          return false;
        }
      }

      clearFieldError(key);
      return true;
    }

    Object.keys(fields).forEach((key) => {
      fields[key].input.addEventListener('input', () => {
        if (fields[key].input.getAttribute('aria-invalid') === 'true') {
          validateField(key);
        }
      });
      fields[key].input.addEventListener('blur', () => validateField(key));
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.hidden = true;
      status.textContent = '';

      const nameValid = validateField('fullName');
      const emailValid = validateField('emailAddress');

      if (!nameValid) {
        fields.fullName.input.focus();
        return;
      }

      if (!emailValid) {
        fields.emailAddress.input.focus();
        return;
      }

      status.textContent = 'Your message is ready to send.';
      status.hidden = false;
      form.reset();
      clearFieldError('fullName');
      clearFieldError('emailAddress');
      document.getElementById('full-name').focus();
    });
  </script>
</body>
